/// Presentation-only translation. Persisted identifiers and user-authored content stay unchanged.
enum AppLanguage {
    static var defaults: UserDefaults {
        ProcessInfo.processInfo.arguments.contains("--uitesting") ? UserDefaults(suiteName: "com.huankecontact.test.language-tests")! : .standard
    }
    static var isChinese: Bool { defaults.string(forKey: "app.language") == "zh-Hans" }
    static var userContent = Set<String>()
    static func setChinese(_ enabled: Bool) { defaults.set(enabled ? "zh-Hans" : "en", forKey: "app.language") }
    static func text(_ source: String) -> String {
        guard isChinese, !userContent.contains(source) else { return source }
        if let translated = translations[source] ?? supplemental[source] { return translated }
        for step in ScreenViewController.steps where source.hasSuffix(".  " + step) {
            return String(source.dropLast(step.count)) + (translations[step] ?? step)
        }
        for separator in [" · ", "\n"] where source.contains(separator) {
            let parts = source.components(separatedBy: separator)
            let translated = parts.map(text)
            if parts != translated { return translated.joined(separator: separator) }
        }
        let patterns: [(String, String)] = [
            (#"^Followers \((.+)\)$"#, "粉丝（$1）"), (#"^Following \((.+)\)$"#, "关注（$1）"),
            (#"^(\d+)h ago$"#, "$1 小时前"), (#"^(\d+)d ago$"#, "$1 天前"),
            (#"^(\d+) items$"#, "$1 项"), (#"^(.+), (\d+) items$"#, "$1，$2 项"),
            (#"^(\d+) comments$"#, "$1 条评论"),
            (#"^(.+) is now in (.+)\.$"#, "$1 已添加到 $2。"),
            (#"^(.+) selected\.$"#, "已选择 $1。"), (#"^(.+) deselected\.$"#, "已取消选择 $1。"),
            (#"^(.+) plan$"#, "$1 布置计划"),
            (#"^(\d+) results$"#, "$1 条结果"),
            (#"^(\d+) of (\d+) steps · In progress$"#, "$1 / $2 步 · 制作中"),
            (#"^(\d+) of (\d+) steps · Finished$"#, "$1 / $2 步 · 已完成"),
            (#"^(\d+) of (\d+) steps$"#, "$1 / $2 步"),
            (#"^✓  (\d+) of (\d+) steps completed$"#, "✓  已完成 $1 / $2 步"),
            (#"^(\d+) min$"#, "$1 分钟"), (#"^(\d+) hours?$"#, "$1 小时"),
            (#"^(\d+) of (\d+)$"#, "$1 / $2"), (#"^(\d+) handmade pieces$"#, "$1 件手作")
        ]
        for (pattern, replacement) in patterns {
            let regex = try! NSRegularExpression(pattern: pattern)
            let range = NSRange(source.startIndex..., in: source)
            if regex.firstMatch(in: source, range: range) != nil { return regex.stringByReplacingMatches(in: source, range: range, withTemplate: replacement) }
        }
        return source
    }
